current_bgm = None

def play_bgm(path, loop=-1, volume=0.5, restart=False):
    global current_bgm

    print("BGM 재생 시도:", path)
    print("파일 존재:", os.path.exists(path))

    if current_bgm == path and not restart:
        print("이미 재생 중인 BGM")
        return

    try:
        pygame.mixer.music.stop()
        pygame.mixer.music.load(path)
        pygame.mixer.music.set_volume(volume)
        pygame.mixer.music.play(loop)
        current_bgm = path
        print("BGM 재생 성공")

    except pygame.error as e:
        print("BGM 재생 실패:", path, e)
        return

    try:
        pygame.mixer.music.stop()
        pygame.mixer.music.load(path)
        pygame.mixer.music.set_volume(volume)
        pygame.mixer.music.play(loop)
        current_bgm = path
        print("BGM 재생 성공")
        print("mixer busy:", pygame.mixer.music.get_busy())

    except pygame.error as e:
        print("BGM 재생 실패:", path, e)


def get_korean_font(size):
    candidates = ["malgungothic", "applegothic", "nanumgothic", "notosanscjk"]
    for name in candidates:
        font = pygame.font.SysFont(name, size)
        if font.get_ascent() > 0:
            return font
    return pygame.font.SysFont(None, size)

