def scale_keep_ratio(img, max_w, max_h):

    w, h = img.get_size()

    scale = min(max_w / w, max_h / h)

    new_w = int(w * scale)
    new_h = int(h * scale)

    return pygame.transform.smoothscale(
        img,
        (new_w, new_h)
    )

