def draw_text_center(text, y, color=WHITE, size_font=None):
    f = size_font if size_font else font
    img = f.render(text, True, color)
    screen.blit(img, (WIDTH // 2 - img.get_width() // 2, y))

def opening_screen():
    
    play_bgm(OPENING_BGM)
    page = 0

    story_pages = [
        (story_img1, "21xx년"),
        (story_img1, "어떠한 세력이 모든 AI를 인간의 적으로 돌리고"),
        (story_img1, "인간의 개체수를 감소 시키고 있다."),
        (story_img2, "오늘도 저런 조무래기들을 상대해야한다"),
        (story_img3, "...!"),
        (story_img4, ""),
        (story_img5, "")
    ]

    typing_start = pygame.time.get_ticks()
    typing_speed = 55
    
    prev_img = None
    fade_start = pygame.time.get_ticks()

    while True:
        
        if page >= len(story_pages):
            tutorial_cutscene()
            return
    
        screen.fill(BLACK)

        if page < len(story_pages):

            img, text = story_pages[page]

            if img is not None:

                img_x = WIDTH // 2 - img.get_width() // 2
                img_y = HEIGHT // 2 - img.get_height() // 2

                fade_time = 1000

                if img != prev_img:
                    fade_start = pygame.time.get_ticks()
                    prev_img = img

                elapsed = pygame.time.get_ticks() - fade_start

                alpha = min(
                    255,
                    int(255 * elapsed / fade_time)
                )

                fade_img = img.copy()

                fade_img.set_alpha(alpha)

                screen.blit(
                    fade_img,
                    (img_x, img_y)
                )

            now = pygame.time.get_ticks()

            visible_count = (now - typing_start) // typing_speed

            current_text = text[:visible_count]

            # 자막 배경
            #pygame.draw.rect(
                #screen,
                #(0, 0, 0),
                #(50, HEIGHT - 110, WIDTH - 100, 90)
            #)

            # 자막 출력
            draw_text_center(
                current_text,
                HEIGHT - 70,
                WHITE
            )

            # 작은 안내문
            small_font = pygame.font.SysFont(None, 24)

            hint = small_font.render(
                "SPACE : next   S : skip",
                True,
                YELLOW
            )

            screen.blit(
                hint,
                (WIDTH - hint.get_width() - 20, HEIGHT - 35)
            )

            pygame.display.flip()

        for e in pygame.event.get():
            if e.type == pygame.QUIT:
                pygame.quit()
                sys.exit()

            if e.type == pygame.KEYDOWN:
                if e.key == pygame.K_SPACE:

                    if page < len(story_pages):
                        visible_count = (pygame.time.get_ticks() - typing_start) // typing_speed

                        if visible_count < len(story_pages[page][1]):
                            typing_start = pygame.time.get_ticks() - len(story_pages[page][1]) * typing_speed
                        else:
                            page += 1
                            typing_start = pygame.time.get_ticks()

                    else:
                        return
                    
                if e.key == pygame.K_s:
                    return

                if e.key == pygame.K_ESCAPE:
                    pygame.quit()
                    sys.exit()
                    
def tutorial_cutscene():
    player = pygame.Rect(90, HEIGHT // 2 - 40, PLAYER_W, PLAYER_H)
    enemy = pygame.Rect(WIDTH - 180, HEIGHT // 2 - 35, ENEMY_W, ENEMY_H)
    stars = [
        [random.randint(0, WIDTH), random.randint(0, HEIGHT), random.randint(1, 2)]
        for _ in range(80)
    ]

    idle_index = 0
    enemy_index = 0

    bullet = pygame.Rect(enemy.x - 40, enemy.centery, BULLET_W, BULLET_H)

    is_kicking = False
    kick_anim_index = 0
    auto_kicked = False
    
    bullet_reflected = False
    enemy_hit = False
    enemy_fall_speed = 0
    enemy_shake = 0
    enemy_hit_index = 0
    
    subtitle = "꺄아아아악!!!"

    after_hit_mode = False

    after_hit_texts = [
        "...어?",
        "총알이 되돌아갔어...?",
        "리듬에 맞춰 차면 싸울 수 있을지도 몰라!"
    ]

    after_hit_index = 0
    
    while True:

        # 별/배경이 있다면 네 실제 플레이 화면의 배경 코드로 교체
        screen.fill(GRAY)

        for s in stars:
            s[0] -= s[2]
            if s[0] < 0:
                s[0] = WIDTH
                s[1] = random.randint(0, HEIGHT)
            pygame.draw.circle(screen, WHITE, (s[0], s[1]), s[2])

        # 총알 천천히 왼쪽 이동
        if not bullet_reflected:
            bullet.x -= 3
        else:
            bullet.x += 8
            
        if bullet_reflected and not enemy_hit and bullet.colliderect(enemy):
            enemy_hit = True
            enemy_shake = 20
            enemy_fall_speed = 5
            enemy_hit_index = 0
            
            after_hit_mode = True
            after_hit_index = 0
            subtitle = after_hit_texts[0]
        
        # 총알이 플레이어 근처에 오면 자동 킥
        if not auto_kicked and bullet.x <= player.right + 30:
            is_kicking = True
            kick_anim_index = 0
            auto_kicked = True
            bullet_reflected = True

        # 플레이어 애니메이션
        if is_kicking:

            kick_anim_index += 0.25

            if kick_anim_index >= len(kick_frames):
                kick_anim_index = len(kick_frames) - 1

            player_frame = kick_frames[int(kick_anim_index)]

        else:

            idle_index += 0.08

            if idle_index >= len(idle_frames):
                idle_index = 0

            player_frame = idle_frames[int(idle_index)]

        player_img = pygame.transform.scale(player_frame, (140, 140))

        screen.blit(
            player_img,
            (player.x - 35, player.y - 35)
        )
        
        # 적 애니메이션
        enemy_index += 0.08
        if enemy_index >= len(enemy_frames):
            enemy_index = 0

        if enemy_hit:
            enemy_hit_index += 0.2
            if enemy_hit_index >= len(enemy_hit_frames):
                enemy_hit_index = len(enemy_hit_frames) - 1

            enemy_frame = enemy_hit_frames[int(enemy_hit_index)]

            if enemy_shake > 0:
                enemy.x += random.randint(-5, 5)
                enemy.y += random.randint(-3, 3)
                enemy_shake -= 1

            enemy.y += enemy_fall_speed
            enemy_fall_speed += 0.2

        else:
            enemy_index += 0.08
            if enemy_index >= len(enemy_frames):
                enemy_index = 0

            enemy_frame = enemy_frames[int(enemy_index)]

        enemy_img = pygame.transform.scale(enemy_frame, (120, 120))
        screen.blit(enemy_img, (enemy.x - 25, enemy.y - 25))

        # 총알 이미지
        screen.blit(
            bullet_img,
            (
                bullet.centerx - bullet_img.get_width() // 2,
                bullet.centery - bullet_img.get_height() // 2
            )
        )

        # 말풍선 위치
        bubble_x = player.x + 20
        bubble_y = player.y - 90
        bubble_font = pygame.font.SysFont("malgungothic", 20)

        text_img = bubble_font.render(subtitle, True, BLACK)

        padding_x = 30
        padding_y = 20

        bubble_w = text_img.get_width() + padding_x
        bubble_h = text_img.get_height() + padding_y

        # 말풍선 본체
        pygame.draw.rect(
            screen,
            WHITE,
            (bubble_x, bubble_y, bubble_w, bubble_h),
            border_radius=12
        )

        # 말풍선 테두리
        pygame.draw.rect(
            screen,
            BLACK,
            (bubble_x, bubble_y, bubble_w, bubble_h),
            2,
            border_radius=12
        )

        # 말풍선 꼬리
        pygame.draw.polygon(
            screen,
            WHITE,
            [
                (bubble_x + 35, bubble_y + bubble_h),
                (bubble_x + 55, bubble_y + bubble_h),
                (bubble_x + 40, bubble_y + bubble_h + 20)
            ]
        )

        pygame.draw.polygon(
            screen,
            BLACK,
            [
                (bubble_x + 35, bubble_y + bubble_h),
                (bubble_x + 55, bubble_y + bubble_h),
                (bubble_x + 40, bubble_y + bubble_h + 20)
            ],
            2
        )

        # 말풍선 안 자막
        bubble_font = pygame.font.SysFont("malgungothic", 23)
        screen.blit(
            text_img,
            (
                bubble_x + bubble_w // 2 - text_img.get_width() // 2,
                bubble_y + bubble_h // 2 - text_img.get_height() // 2
            )
        )

        small_font = pygame.font.SysFont(None, 24)
        hint = small_font.render("SPACE : continue   S : skip", True, YELLOW)
        screen.blit(hint, (WIDTH - hint.get_width() - 20, HEIGHT - 35))

        pygame.display.flip()

        for e in pygame.event.get():
            if e.type == pygame.QUIT:
                pygame.quit()
                sys.exit()

            if e.type == pygame.KEYDOWN:
                if e.key == pygame.K_SPACE:

                    # 적 맞은 이후에만 SPACE 허용
                    if after_hit_mode:

                        after_hit_index += 1

                        if after_hit_index >= len(after_hit_texts):
                            return

                        subtitle = after_hit_texts[after_hit_index]

                if e.key == pygame.K_s:
                    return

                if e.key == pygame.K_ESCAPE:
                    pygame.quit()
                    sys.exit()

        clock.tick(60)

def game_over_screen(score):
    while True:
        screen.fill(BLACK)
        draw_text_center("GAME OVER", 150, RED, font_big)
        draw_text_center(f"Score: {score}", 240, WHITE)
        draw_text_center("R : Restart    Q : Quit", 320, YELLOW)
        pygame.display.flip()

        for e in pygame.event.get():
            if e.type == pygame.QUIT:
                pygame.quit()
                sys.exit()
            if e.type == pygame.KEYDOWN:
                if e.key == pygame.K_r:
                    main(False)
                if e.key == pygame.K_q:
                    pygame.quit()
                    sys.exit()
                    
def pause_screen():
    pygame.mixer.music.pause()
    pause_start = pygame.time.get_ticks()

    while True:
        screen.fill(BLACK)

        draw_text_center("PAUSED", 180, WHITE, font_big)
        draw_text_center("SPACE : Continue", 280, GREEN)
        draw_text_center("Q : Quit", 340, RED)

        pygame.display.flip()

        for e in pygame.event.get():
            if e.type == pygame.QUIT:
                pygame.quit()
                sys.exit()

            if e.type == pygame.KEYDOWN:
                if e.key == pygame.K_SPACE or e.key == pygame.K_ESCAPE:
                    pygame.mixer.music.unpause()
                    return pygame.time.get_ticks() - pause_start

                if e.key == pygame.K_q:
                    pygame.quit()
                    sys.exit()

def clear_screen(score):
    while True:
        screen.fill(BLACK)
        draw_text_center("CLEAR!", 150, GREEN, font_big)
        draw_text_center(f"Final Score: {score}", 240, WHITE)
        draw_text_center("R : Restart    Q : Quit", 320, YELLOW)
        pygame.display.flip()

        for e in pygame.event.get():
            if e.type == pygame.QUIT:
                pygame.quit()
                sys.exit()
            if e.type == pygame.KEYDOWN:
                if e.key == pygame.K_r:
                    return True
                if e.key == pygame.K_q:
                    pygame.quit()
                    sys.exit()

